import{z as E,x as p,o as r,c as d,q as i,j as l,D as s,d as n,s as o,S as A,b as e}from"./chunks/framework.C8m1ZpeB.js";const g=JSON.parse('{"title":"虚拟内存分页","description":"","frontmatter":{"title":"虚拟内存分页","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/paging-vm.md","filePath":"cs/paging-vm.md","lastUpdated":1791413859000}'),B={name:"cs/paging-vm.md"};function c(m,a,h,P,D,f){const t=p("Mermaid");return r(),d("div",null,[a[2]||(a[2]=i('<h1 id="虚拟内存分页" tabindex="-1">虚拟内存分页 <a class="header-anchor" href="#虚拟内存分页" aria-label="Permalink to &quot;虚拟内存分页&quot;">​</a></h1><div class="epigraph"><p>给每个进程一套连续的虚拟地址，用页表把它映到不一定连续、也不一定都在 DRAM 里的物理页。</p><footer>—— 据 Patterson and Hennessy, Computer Organization and Design (RISC-V)；Hennessy and Patterson, CA:AQA 整理</footer></div><p><a href="/cs/inclusive-exclusive-cache">上一课</a>定下包含或互斥的层次约定，<a href="/cs/cache-miss-types">缺失分类</a>把 cache 缺失分成三类。Cache 仍用物理或虚拟地址去索引 SRAM，地址空间大小等于程序员看见的 DRAM 窗口时，保护与隔离还没有对象。<a href="/cs/privilege-rings">特权级</a>已经禁止用户直接碰机器状态，但还没有把「用户的指针」和「DRAM 的行」分开。<a href="/cs/locality-principle">局部性原理</a>在页这一级同样适用。本课不重讲 cache 标签。缺口是：程序要用的地址空间可以大于物理内存，且各进程必须看不见别人的物理页。本课只钉页、页表与缺页。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>若程序直接发出物理地址，链接时就要固定装入位置，进程之间也无法用同一套指针约定。DRAM 不够时，只能整程序换入换出。缺口不是再做一块更大的 cache，而是<strong>固定大小的页：虚拟页号经页表变成物理页号，页内偏移原样通过</strong>。</p><p><span class="marginnote">数字实例：页大小 4 KiB 就是 \\(2^{12}\\) 字节，所以地址低 12 位是页内偏移，翻译时原样照抄；一个 48 位虚拟地址剩下高 36 位全是虚拟页号，拿它当页表数组的下标去查。偏移不用译、只译高位，这是分页便宜的根源。</span></p><p>缺页：页表项无效或页不在 DRAM，陷入内核，从磁盘取页——粒度是页，不是 cache 行。本课不把磁盘调度写进来。</p><p><span class="marginnote">页是保护与换入的单位；cache 行是延迟隐藏的单位。两者都吃局部性，但缺失代价差几个数量级。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>虚拟地址切成 VPN 与页内偏移。页表是 VPN 到 PPN 的数组，附带有效、可写、用户可访问等位。<a href="/cs/privilege-rings">特权级</a>下，用户访问若越权，精确异常路径已经准备好。命中则物理地址 = PPN 拼接偏移，再进 cache 与<a href="/cs/memory-array-sram-dram">SRAM 与 DRAM 阵列</a>。</p><p><span class="marginnote">常见误区：初学者容易以为页表是一种计算（拿地址做运算算出物理地址）。它其实就是一张普通数组：VPN 当下标，取出来的表项就是物理页号，外加几个权限位。也正因为是「每进程一张表」，换进程时换个表基址，同一套虚拟地址立刻指向另一片物理页。</span></p>',11)),(r(),l(A,null,{default:s(()=>[o(t,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20LR%0A%20%20VA%5B%22%E8%99%9A%E6%8B%9F%E5%9C%B0%E5%9D%80%22%5D%20--%3E%20VPN%5B%22VPN%22%5D%0A%20%20VA%20--%3E%20OFF%5B%22%E9%A1%B5%E5%86%85%E5%81%8F%E7%A7%BB%22%5D%0A%20%20VPN%20--%3E%20PT%5B%22%E9%A1%B5%E8%A1%A8%22%5D%0A%20%20PT%20--%3E%20PPN%5B%22PPN%22%5D%0A%20%20PPN%20--%3E%20PA%5B%22%E7%89%A9%E7%90%86%E5%9C%B0%E5%9D%80%22%5D%0A%20%20OFF%20--%3E%20PA%0A"})]),fallback:s(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,"每个进程一份页表（或根指针不同）。内核在特权态改页表；用户只看见虚拟地址。后课 TLB 才会说查页表本身也是访存。",-1)),a[4]||(a[4]=e("h2",{id:"机制",tabindex:"-1"},[n("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=e("p",null,"分页让装入地址无关：编译用虚拟 0，内核随便找空物理页。换页让工作集留在 DRAM，其余在磁盘——Denning 工作集在这里成为容量问题的页版。Cache 仍处理字与行；本课不把页表项缓存在数据 cache 里讲完。",-1)),a[6]||(a[6]=e("p",null,[e("span",{class:"marginnote"},"直觉类比：DRAM 是你手边的书桌，磁盘是书架。桌子放不下的书放书架，要看哪本再搬哪本（换页）；每本书都按固定 4 KiB 的册子装订（页），搬动粒度统一，桌面上怎么摆也和书架上的位置无关（装入地址无关）。")],-1)),a[7]||(a[7]=e("p",null,"第一张图回答「一个地址怎么翻译」；进程隔离从哪里来——同一虚拟号在两张页表里各查各的——是另一个问题。",-1)),(r(),l(A,null,{default:s(()=>[o(t,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20LR%0A%20%20A%5B%22%E8%BF%9B%E7%A8%8B%20A%20%E8%AE%BF%E9%97%AE%20VPN%200%22%5D%20--%3E%20TA%5B%22A%20%E7%9A%84%E9%A1%B5%E8%A1%A8%22%5D%20--%3E%20F5%5B%22%E7%89%A9%E7%90%86%E5%B8%A7%205%22%5D%0A%20%20B%5B%22%E8%BF%9B%E7%A8%8B%20B%20%E8%AE%BF%E9%97%AE%20VPN%200%22%5D%20--%3E%20TB%5B%22B%20%E7%9A%84%E9%A1%B5%E8%A1%A8%22%5D%20--%3E%20F2%5B%22%E7%89%A9%E7%90%86%E5%B8%A7%202%22%5D%0A%20%20TB%20-.-%3E%7C%22B%20%E7%9A%84%E8%A1%A8%E9%87%8C%E6%9F%A5%E4%B8%8D%E5%88%B0%E5%B8%A7%205%22%7C%20ISO%5B%22%E5%90%8C%E4%B8%80%E8%99%9A%E6%8B%9F%E5%8F%B7%20%E5%90%84%E8%A7%81%E5%90%84%E7%9A%84%E7%89%A9%E7%90%86%E9%A1%B5%22%5D%0A"})]),fallback:s(()=>[...a[1]||(a[1]=[n(" Loading... ",-1)])]),_:1})),a[8]||(a[8]=i('<p>写权限位让<a href="/cs/write-back-allocate">写回与写分配</a>那一套脏数据在页级也有对应：页脏则换出时要写磁盘。本课只承认这一位存在。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课用单级页表，不管 64 位空间下表有多大——那是<a href="/cs/multi-level-page-table">多级页表</a>。也不引入 TLB。Cache 用物理标签还是虚拟索引，是实现选择，本课只要求最终比较发生在翻译之后或与翻译一致。</p><p>后课默认：load/store 发出虚拟地址；不在页表或权限失败则缺页异常。翻译延迟必须被下一课藏住。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>虚拟页号经页表变物理页号；偏移不译。</li><li>缺页是页级容量/强制问题，代价远高于 cache 缺失。</li><li>TLB 与多级页表是后课的缺口。</li><li>出处：Patterson and Hennessy, <em>COD</em> RISC-V；Hennessy and Patterson, <em>CA:AQA</em> 虚拟内存。</li></ul>',6))])}const T=E(B,[["render",c]]);export{g as __pageData,T as default};
